import { useFrame, useThree } from '@react-three/fiber'
import { useEffect, useRef } from 'react'

/**
 * Диагностика рендера для headless-прогонов: после кадра читает реальный
 * пиксель из буфера и пишет результат в document.title, чтобы читать его
 * через `chromium --dump-dom`.
 */
export function RenderProbe({ sampleAt = [0.5, 0.5] }: { sampleAt?: [number, number] }) {
  const gl = useThree((s) => s.gl)
  const size = useThree((s) => s.size)
  const frames = useRef(0)

  useEffect(() => {
    document.title = `PROBE init size=${size.width}x${size.height} buf=${gl.domElement.width}x${gl.domElement.height}`
  }, [size.width, size.height, gl])

  useFrame(() => {
    frames.current += 1
    // приоритет 2 — после рендера EffectComposer (он занимает priority 1)
  }, 2)

  useFrame(({ gl: renderer }) => {
    if (frames.current < 3) return
    const ctx = renderer.getContext()
    const w = renderer.domElement.width
    const h = renderer.domElement.height
    const px = new Uint8Array(4)
    const x = Math.floor(w * sampleAt[0])
    const y = Math.floor(h * sampleAt[1])
    try {
      ctx.readPixels(x, y, 1, 1, ctx.RGBA, ctx.UNSIGNED_BYTE, px)
      document.title = `PROBE f=${frames.current} canvas=${renderer.domElement.clientWidth}x${renderer.domElement.clientHeight} buf=${w}x${h} px(${x},${y})=${px[0]},${px[1]},${px[2]} calls=${renderer.info.render.calls}`
    } catch (e) {
      document.title = `PROBE readPixels fail ${String(e).slice(0, 120)}`
    }
    frames.current = -1e6
  }, 3)

  return null
}

#!/usr/bin/env node
/**
 * Детерминированный захват кадров через Playwright + системный Chromium.
 * Ждёт сигнала `window.__ready` от сцены и только потом снимает кадр —
 * в отличие от `chromium --screenshot`, который может снять недоприсованный буфер.
 *
 * usage: node tools/capture.mjs <url> <out.png> [w] [h] [readyTimeoutMs]
 */
import { chromium } from 'playwright-core'

const [url, out, w = '1280', h = '720', readyTimeout = '90000'] = process.argv.slice(2)

const browser = await chromium.launch({
  executablePath: process.env.CHROME_PATH || '/usr/bin/chromium',
  args: [
    '--no-sandbox',
    '--use-gl=angle',
    '--use-angle=swiftshader',
    '--enable-unsafe-swiftshader',
    '--disable-dev-shm-usage',
  ],
})

const page = await browser.newPage({
  viewport: { width: +w, height: +h },
  deviceScaleFactor: 1,
})

const logs = []
page.on('console', (m) => logs.push(`[${m.type()}] ${m.text()}`))
page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`))

await page.goto(url, { waitUntil: 'load', timeout: 60000 })

// сцена выставляет window.__ready после стабильных кадров
let ready = true
try {
  await page.waitForFunction('window.__ready === true', null, { timeout: +readyTimeout })
} catch {
  ready = false
}

await page.waitForTimeout(1200)

await page.screenshot({ path: out })
await browser.close()

const diag = await (async () => {
  try {
    return ''
  } catch {
    return ''
  }
})()

console.log(`OK ${out} ready=${ready}`)
if (logs.length) console.log('--- консоль страницы ---\n' + logs.slice(0, 20).join('\n'))
void diag

import { useFrame, useThree } from '@react-three/fiber'
import { useEffect, useRef } from 'react'

/**
 * Ставит window.__ready после нескольких стабильных кадров — сигнал для
 * headless-захвата (tools/capture.mjs), чтобы снимать уже дорисованный кадр.
 * Опционально пишет диагностику в document.title.
 */
export function RenderProbe({
  warmupFrames = 3,
  onReady,
  probe = false,
}: {
  warmupFrames?: number
  onReady?: () => void
  probe?: boolean
}) {
  const gl = useThree((s) => s.gl)
  const size = useThree((s) => s.size)
  const count = useRef(0)
  const announced = useRef(false)
  const done = useRef(false)

  useEffect(() => {
    if (probe) {
      document.title = `PROBE init size=${size.width}x${size.height} buf=${gl.domElement.width}x${gl.domElement.height}`
    }
  }, [gl, size.width, size.height, probe])

  useFrame(() => {
    if (announced.current) return
    count.current += 1
    if (count.current < warmupFrames) return
    announced.current = true

    if (probe) {
      const ctx = gl.getContext()
      const w = gl.domElement.width
      const h = gl.domElement.height
      const px = new Uint8Array(4)
      try {
        ctx.readPixels(Math.floor(w / 2), Math.floor(h / 2), 1, 1, ctx.RGBA, ctx.UNSIGNED_BYTE, px)
        document.title = `PROBE canvas=${gl.domElement.clientWidth}x${gl.domElement.clientHeight} buf=${w}x${h} center=${px[0]},${px[1]},${px[2]} calls=${gl.info.render.calls} tris=${gl.info.render.triangles}`
      } catch (e) {
        document.title = `PROBE readPixels fail ${String(e).slice(0, 140)}`
      }
    }

    // сигнал готовности после реального кадра
    requestAnimationFrame(() => {
      setTimeout(() => {
        ;(window as unknown as { __ready?: boolean }).__ready = true
        onReady?.()
      }, 60)
    })
  })

  void done
  return null
}

