        <group position={[0, 0, 0]}>
          <Detective
            clip={q.get('clip') ?? 'Idle'}
            time={parseFloat(q.get('t') ?? '0')}
            rotationY={parseFloat(q.get('ry') ?? '0')}
            scale={parseFloat(q.get('scale') ?? '1')}
          />
        </group>

        {/* пол сеткой для ощущения масштаба */}
        <mesh rotation={[-Math.PI / 2, 0, 0]} receiveShadow position={[0, 0, 0]}>
          <circleGeometry args={[3, 64]} />
          <meshStandardMaterial color="#14161d" roughness={0.85} metalness={0.05} />
        </mesh>
        <Grid
          args={[6, 6]}
          cellSize={0.25}
          cellColor="#2a3040"
          sectionSize={1}
          sectionColor="#3d4759"
          fadeDistance={7}
          position={[0, 0.002, 0]}
        />

        <Turntable />
        <CameraRig />
        <ProceduralEnv intensity={1.0} />
        <RenderProbe probe={q.has('probe')} />
      </>
    )
  }

  return (
    <>
      {/* ночная палитра Ноктиса: холодный лунный ключ + тёплые уличные фонари */}
      <color attach="background" args={['#0a0f1c']} />
      <fogExp2 attach="fog" args={['#131a2b', 0.0115]} />

      <ambientLight intensity={0.5} color="#6d8cc4" />
      <hemisphereLight args={['#8fb0e8', '#1a1c24', 0.55]} />
      <directionalLight
        castShadow
        position={[-14, 22, -10]}
        intensity={1.5}
        color="#b6cbf2"
        shadow-mapSize={[1536, 1536]}
        shadow-camera-near={1}
        shadow-camera-far={90}
        shadow-camera-left={-32}
        shadow-camera-right={32}
        shadow-camera-top={32}
        shadow-camera-bottom={-32}
        shadow-bias={-0.0006}
        shadow-normalBias={0.03}
      />

      <NoirStreet />
      {q.has('herob') && (
        <Detective
          clip={q.get('clip') ?? 'Idle'}
          time={parseFloat(q.get('t') ?? '0')}
          position={[1.2, 0.18, 2]}
          rotationY={parseFloat(q.get('ry') ?? '0')}
        />
      )}
      <CameraRig />
      <ProceduralEnv intensity={1.1} />
      <RenderProbe probe={q.has('probe')} />
      <EnvFallback />
    </>
  )
}

function EnvFallback() {
  void Environment
  void Lightformer
  void OrbitControls
  void Stage
  void useSearchParams
  return null
}

import { useFrame, useThree } from '@react-three/fiber'
import { useRef } from 'react'

/**
 * Вращение камеры вокруг модели для turntable-ракурсов.
 * Угол задаётся параметром ?spin=<градусы> — детерминированно, без анимации,
 * чтобы покадрово рендерить видео.
 */
export function Turntable({ enabled = true }: { enabled?: boolean }) {
  const { camera } = useThree()
  const applied = useRef(false)
  const q = new URLSearchParams(location.search)
  const spin = parseFloat(q.get('spin') ?? '0')

  useFrame(() => {
    if (!enabled || applied.current) return
    applied.current = true
    const a = (spin * Math.PI) / 180
    const dist = parseFloat(q.get('dist') ?? '3.2')
    const el = (parseFloat(q.get('el') ?? '6') * Math.PI) / 180
    const ty = parseFloat(q.get('ty') ?? '1.0')
    const x = Math.sin(a) * dist * Math.cos(el)
    const z = Math.cos(a) * dist * Math.cos(el)
    const y = ty + dist * Math.sin(el)
    camera.position.set(x, y, z)
    camera.lookAt(0, ty, 0)
  })

  return null
}

/** Минимальный хук чтения query-параметров (используется точечно). */
import { useMemo } from 'react'

export function useSearchParams() {
  return useMemo(() => new URLSearchParams(location.search), [])
}

